-- TASK-207: 24 independent style-matched original V4 questions; NO edits to 255 published V2/V3 rows.
-- Demo patterns: Demo2026 PDF6 Q12 (flow function), 20000 LIK PDF6 Q13-Q14 (DAG paths, flow trace), Informatika Demo PDF18 Q35 (flow purpose).
BEGIN;
DO $insert$
DECLARE q jsonb;qid uuid;sid uuid;cid uuid;lid uuid;ord int;item text;oid uuid;opts jsonb;rights jsonb;payload jsonb;v jsonb;mapping jsonb;list_ids jsonb;
BEGIN
SELECT id INTO sid FROM public.subjects WHERE code='informatika';
IF sid IS NULL THEN RAISE EXCEPTION 'Missing subject';END IF;
FOR q IN SELECT value FROM jsonb_array_elements('[{"id":"001","fmt":"Y1","stem":"Blok-sxema boshlang‘ich P=1, i=3 qiymatlari bilan ishlaydi. Diagramdagi sikl tugagach, P ning qiymati qancha?","options":["54","18","162","486"],"correct":2,"explanation":"i=3, 6, 9; P=1·3·6·9=162. i=12 da i≤9 sharti yolg‘on bo‘ladi.","lesson":"algoritmlash-v2-04","construct":"S3.ALGO.03","style":"flowchart_function","asset":"flow_product_3_9","difficulty":4},{"id":"002","fmt":"Y1","stem":"Diagramdagi P:=P·i amali ikkinchi marta bajarilgandan keyin P nechaga teng?","options":["54","18","3","162"],"correct":1,"explanation":"Birinchi ko‘paytirishda P=3, ikkinchisida P=3·6=18. Yakuniy qiymat 162 bilan adashtirmang.","lesson":"algoritmlash-v2-04","construct":"S3.ALGO.03","style":"flowchart_trace","asset":"flow_product_3_9","difficulty":3},{"id":"003","fmt":"Y1","stem":"Diagramdagi algoritmga a qiymatlari ketma-ket 6, 8, −2, 3 ko‘rinishida kiritilsa, chiqarilgan S qancha?","options":["14","12","16","17"],"correct":0,"explanation":"S=0→6→14; −2 manfiy bo‘lgani uchun natija chiqariladi, 3 o‘qilmaydi.","lesson":"algoritmlash-v3-shart-keyin-sikl","construct":"S3.ALGO.03","style":"sentinel_flowchart","asset":"flow_until_negative","difficulty":4},{"id":"004","fmt":"Y1","stem":"Xuddi shu algoritmga dastlab a=−4 kiritilsa, qanday S chiqariladi?","options":["−4","4","1","0"],"correct":3,"explanation":"Shart avval manfiylikni tekshiradi, shuning uchun boshlang‘ich S=0 chiqariladi.","lesson":"algoritmlash-v3-shart-keyin-sikl","construct":"S3.ALGO.03","style":"sentinel_edge","asset":"flow_until_negative","difficulty":3},{"id":"005","fmt":"Y1","stem":"Yo‘naltirilgan grafda faqat strelkalar bo‘yicha yurish mumkin. A dan J gacha necha xil yo‘l mavjud?","options":["6","7","8","9"],"correct":2,"explanation":"J ga H orqali 5 yo‘l, I orqali 3 yo‘l keladi. Jami 5+3=8; sikl yo‘q.","lesson":"algoritmlash-v2-07","construct":"S3.ALGO.04","style":"dag_path_count","asset":"dag_paths_a_j","difficulty":5},{"id":"006","fmt":"Y1","stem":"Grafdagi E→I yo‘li yopib qo‘yilsa, A dan J gacha nechta yo‘l qoladi?","options":["5","7","8","6"],"correct":3,"explanation":"Dastlab 8 yo‘l, A dan E ga 2 usul (B yoki C orqali) keladi. E→I yopilganda shu 2 yo‘l yo‘qoladi: 6.","lesson":"algoritmlash-v2-07","construct":"S3.ALGO.04","style":"dag_counterfactual","asset":"dag_paths_a_j","difficulty":5},{"id":"007","fmt":"Y1","stem":"S:=0. i 1 dan 7 gacha oshiriladi; faqat toq i uchun S:=S+i·i bajariladi. Yakuniy S ni toping.","options":["49","35","64","84"],"correct":3,"explanation":"Toq qiymatlar 1,3,5,7; 1²+3²+5²+7²=1+9+25+49=84.","lesson":"algoritmlash-v2-04","construct":"S3.ALGO.03","style":"trace_condition_loop","asset":null,"difficulty":4},{"id":"008","fmt":"Y1","stem":"K:=0; FOR i:=1..4 DO FOR j:=1..i DO IF (i+j) MOD 2=0 THEN K:=K+1. K nechaga teng?","options":["6","10","4","5"],"correct":0,"explanation":"Mos juftliklar i=1 uchun 1, i=2 uchun 1, i=3 uchun 2, i=4 uchun 2. Jami 6.","lesson":"algoritmlash-v2-05","construct":"S3.ALGO.03","style":"nested_loop_trace","asset":null,"difficulty":5},{"id":"009","fmt":"Y1","stem":"x:=3; s:=2. FOR i:=1..4: agar i toq bo‘lsa x:=x+1, aks holda s:=s·x. Yakuniy s?","options":["25","32","40","50"],"correct":2,"explanation":"i=1 da x=4; i=2 da s=8; i=3 da x=5; i=4 da s=40.","lesson":"algoritmlash-v2-06","construct":"S3.ALGO.03","style":"interleaved_trace","asset":null,"difficulty":5},{"id":"010","fmt":"Y1","stem":"i:=2; K:=0; WHILE i<8 DO { K:=K+1; i:=i+3 }. Yakuniy K?","options":["3","2","1","4"],"correct":1,"explanation":"i 2 va 5 da shart rost; keyingi i=8 bo‘lganda 8<8 yolg‘on. K=2.","lesson":"algoritmlash-v3-shart-keyin-sikl","construct":"S3.ALGO.03","style":"while_boundary","asset":null,"difficulty":3},{"id":"011","fmt":"Y1","stem":"x:=0; REPEAT x:=x+4 UNTIL x>=11. Yakuniy x?","options":["8","11","16","12"],"correct":3,"explanation":"x 4→8→12 bo‘ladi; shart tanadan keyin tekshiriladi, 12 da rost.","lesson":"algoritmlash-v3-shart-keyin-sikl","construct":"S3.ALGO.03","style":"repeat_until_trace","asset":null,"difficulty":4},{"id":"012","fmt":"Y1","stem":"S:=0; manfiy son kiritilguncha faqat manfiy bo‘lmagan qiymatlar qo‘shiladi. 2,0,4,−1,8 kiritilsa S?","options":["6","5","14","−1"],"correct":0,"explanation":"2+0+4=6; −1 to‘xtash belgisi va 8 o‘qilmaydi.","lesson":"algoritmlash-v3-shart-keyin-sikl","construct":"S3.ALGO.03","style":"sentinel_algorithm","asset":null,"difficulty":3},{"id":"013","fmt":"Y1","stem":"1 dan 50 gacha bo‘lgan sonlar yig‘indisini n(n+1)/2 formulasi bilan hisoblasak, natija?","options":["1250","1225","1275","2550"],"correct":2,"explanation":"50·51/2=1275. Formula takroriy qo‘shish bilan bir xil natijani beradi.","lesson":"algoritmlash-v2-08","construct":"S3.ALGO.04","style":"formula_efficiency","asset":null,"difficulty":3},{"id":"014","fmt":"Y1","stem":"MAX:=0 boshlanib, ro‘yxatdagi −11, −4, −7 sonlari bilan faqat (son>MAX) bo‘lsa yangilanadi. Noto‘g‘ri algoritm nimani qaytaradi?","options":["−4","0","−11","−7"],"correct":1,"explanation":"Har bir manfiy son 0 dan kichik; MAX o‘zgarmay 0 bo‘lib qoladi. Bu noto‘g‘ri javob.","lesson":"algoritmlash-v2-06","construct":"S3.ALGO.03","style":"bug_detection","asset":null,"difficulty":3},{"id":"015","fmt":"Y1","stem":"K:=0; FOR i:=1..20 DO IF (i MOD 2=0 AND i MOD 3=0) THEN K:=K+1. K?","options":["2","4","5","3"],"correct":3,"explanation":"2 ga ham 3 ga ham bo‘linadiganlar 6,12,18 — 3 ta.","lesson":"algoritmlash-v2-05","construct":"S3.ALGO.03","style":"compound_condition_loop","asset":null,"difficulty":4},{"id":"016","fmt":"Y1","stem":"Qoldiqli Yevklid algoritmi yordamida EKUB(84,30) ni toping.","options":["6","12","3","14"],"correct":0,"explanation":"84 mod 30=24; 30 mod 24=6; 24 mod 6=0. EKUB=6.","lesson":"algoritmlash-v2-07","construct":"S3.ALGO.03","style":"euclid_trace","asset":null,"difficulty":3},{"id":"017","fmt":"Y1","stem":"FOR i:=1..4 DO FOR j:=i..4 DO K:=K+1, K dastlab 0. Yakunda K?","options":["16","10","8","6"],"correct":1,"explanation":"Ichki takrorlar soni 4+3+2+1=10; ikki sikl oralig‘i o‘zgaruvchiga bog‘liq.","lesson":"algoritmlash-v2-04","construct":"S3.ALGO.03","style":"nested_triangular_trace","asset":null,"difficulty":4},{"id":"018","fmt":"Y1","stem":"IF x>=10 sharti chegarada to‘g‘ri ishlashini tekshirish uchun eng foydali kirish juftligi?","options":["1 va 2","20 va 30","9 va 10","−20 va −10"],"correct":2,"explanation":"9 da yolg‘on, 10 da rost; aynan chegara yonidagi ikkita holat tekshiriladi.","lesson":"algoritmlash-v2-06","construct":"S3.ALGO.02","style":"boundary_testing","asset":null,"difficulty":3},{"id":"019","fmt":"Y1","stem":"Bir xil muammo uchun A algoritmi 4n amal, B algoritmi n² amal bajaradi. n=5 da qaysi biri kamroq amal talab qiladi?","options":["B: 5 ta amal","Ikkalasi 20 amal","B: 25 ta amal eng kam","A: 20 ta amal"],"correct":3,"explanation":"A=4·5=20, B=5²=25. Aynan n=5 uchun A kamroq amal talab qiladi.","lesson":"algoritmlash-v2-08","construct":"S3.ALGO.04","style":"efficiency_comparison","asset":null,"difficulty":4},{"id":"020","fmt":"Y1","stem":"P:=1; FOR i:=1..6 DO IF i MOD 2=0 THEN P:=P·i. Yakuniy P?","options":["48","720","24","12"],"correct":0,"explanation":"Faqat juftlar 2,4,6 ko‘paytiriladi: 1·2·4·6=48.","lesson":"algoritmlash-v2-05","construct":"S3.ALGO.03","style":"filtered_product","asset":null,"difficulty":4},{"id":"021","fmt":"Y2","stem":"Uch algoritmning bajarilishidan olingan yakuniy qiymatlarni moslang.","left":["S:=0; i=1..3 uchun S:=S+i","P:=1; i=1..4 uchun P:=P·i","K:=0; i=1..6 uchun, i mod 3=0 bo‘lsa K:=K+1"],"right":["24","2","6"],"pairs":[[0,2],[1,0],[2,1]],"explanation":"Yig‘indi 6; faktorial 24; 3 va 6 uchun hisoblagich 2.","lesson":"algoritmlash-v2-06","construct":"S3.ALGO.03","style":"matching_trace","difficulty":4},{"id":"022","fmt":"Y2","stem":"Siklning boshlang‘ich holatini tana bajarilishi soni bilan moslang.","left":["WHILE boshi: shart yolg‘on","REPEAT–UNTIL boshi: chiqish sharti rost","FOR i:=3..5 (qadam 1)"],"right":["Tana kamida 1 marta bajariladi","Tana 0 marta bajariladi","Tana 3 marta bajariladi"],"pairs":[[0,1],[1,0],[2,2]],"explanation":"WHILE boshida chiqadi; UNTIL tana oxirida tekshiriladi; FOR uch qiymatga ega.","lesson":"algoritmlash-v3-shart-keyin-sikl","construct":"S3.ALGO.02","style":"matching_loop_behavior","difficulty":4},{"id":"023","fmt":"Y3","stem":"S:=1, i:=1 boshlang‘ich qiymatlarda 1 dan 4 gacha ko‘paytma olish algoritmi amallarini mantiqiy tartiblang.","left":["Agar i<=4 bo‘lsa, sikl tanasiga o‘tish","S:=1 va i:=1 boshlang‘ich qiymatlarni belgilash","S:=S·i amali","i:=i+1; shartni qayta tekshirish","Shart yolg‘on bo‘lsa S ni chiqarish"],"order":[1,0,2,3,4],"explanation":"Boshlang‘ichlash → shart → ko‘paytirish → yangilash → shartga qaytish/chiqarish.","lesson":"algoritmlash-v2-04","construct":"S3.ALGO.03","style":"ordering_trace","difficulty":4},{"id":"024","fmt":"Y3","stem":"Yo‘naltirilgan asiklik grafda A dan J gacha yo‘llar sonini hisoblash uchun bosqichlarni tartiblang.","left":["Oxirgi J tuguniga kelgan yo‘llarni qo‘shish","Boshlang‘ich A tuguniga 1 yo‘l deb belgilash","A dan chiqishlar B,C,D uchun qiymatlarni tarqatish","Keyingi E,F,G tugunlarida kelgan yo‘llarni yig‘ish","H,I oraliq tugunlaridagi yo‘llar sonini aniqlash"],"order":[1,2,3,4,0],"explanation":"Dinamik sanash: A=1; B,C,D=1; E=2,F=3,G=1; H=5,I=3; J=8.","lesson":"algoritmlash-v2-07","construct":"S3.ALGO.04","style":"ordering_graph","difficulty":4}]'::jsonb) LOOP
 IF EXISTS(SELECT 1 FROM public.questions WHERE source_reference='algoritmlash-v4:ALG-V4-'||(q->>'id')) THEN CONTINUE;END IF;
 SELECT id INTO cid FROM public.constructs WHERE code=q->>'construct';
 SELECT id INTO lid FROM public.lessons WHERE slug=q->>'lesson';
 -- TASK-205 is still a separate PR: on a clean main database the V3 lesson may not exist.
 IF lid IS NULL AND q->>'lesson'='algoritmlash-v3-shart-keyin-sikl' THEN
  SELECT id INTO lid FROM public.lessons WHERE slug='algoritmlash-v2-04';
 END IF;
 IF cid IS NULL OR lid IS NULL THEN RAISE EXCEPTION 'Missing construct/lesson %',q->>'id'; END IF;
 qid:=gen_random_uuid();
 INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
 VALUES(qid,sid,cid,'S3.ALGO',(q->>'fmt')::question_format,
 (CASE WHEN (q->>'difficulty')::int<=2 THEN 'bilish' WHEN (q->>'difficulty')::int<=3 THEN 'qollash' ELSE 'mulohaza' END)::cognitive_level,
 (q->>'difficulty')::int,q->>'stem',
 CASE WHEN q->>'asset' IS NOT NULL THEN jsonb_build_array(jsonb_build_object('kind','image','diagram_id',q->>'asset','src','/algoritmlash-v4/'||(q->>'asset')||'.svg','alt','Original algoritm/graf blok-sxemasi')) ELSE '[]'::jsonb END,
 true,'review'::content_status,'algoritmlash-v4:ALG-V4-'||(q->>'id'),lid);
 opts:='[]'::jsonb;rights:='[]'::jsonb;
 IF q->>'fmt'='Y1' THEN
 FOR item,ord IN SELECT value,(ordinality::int-1) FROM jsonb_array_elements_text(q->'options') WITH ORDINALITY LOOP
 oid:=gen_random_uuid();INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(oid,qid,'a',ord,item);
 opts:=opts||jsonb_build_array(oid::text);
 END LOOP;
 payload:=jsonb_build_object('correct_option_id',opts->>(q->>'correct')::int);
 ELSE
 FOR item,ord IN SELECT value,(ordinality::int-1) FROM jsonb_array_elements_text(q->'left') WITH ORDINALITY LOOP
 oid:=gen_random_uuid();INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(oid,qid,'a',ord,item);
 opts:=opts||jsonb_build_array(oid::text);
 END LOOP;
 IF q->>'fmt'='Y2' THEN
 FOR item,ord IN SELECT value,(ordinality::int-1) FROM jsonb_array_elements_text(q->'right') WITH ORDINALITY LOOP
 oid:=gen_random_uuid();INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(oid,qid,'b',ord,item);
 rights:=rights||jsonb_build_array(oid::text);
 END LOOP;
 mapping:='{}'::jsonb;
 FOR v IN SELECT value FROM jsonb_array_elements(q->'pairs') LOOP
 mapping:=mapping||jsonb_build_object(opts->>(v->>0)::int,rights->>(v->>1)::int);
 END LOOP;
 payload:=jsonb_build_object('pairs',mapping);
 ELSIF q->>'fmt'='Y3' THEN
 list_ids:='[]'::jsonb;
 FOR v IN SELECT value FROM jsonb_array_elements(q->'order') LOOP
 list_ids:=list_ids||jsonb_build_array(opts->>(v::text)::int);
 END LOOP;
 payload:=jsonb_build_object('order',list_ids);
 END IF;
 END IF;
 INSERT INTO public.question_keys(question_id,payload,explanation_md)
 VALUES(qid,payload,(q->>'explanation')||E'\n\nTASK-207 uslub namunalari: Demo2026 PDF 6 (Q12); 20000 LIK informatika PDF 6 (Q13–14); Informatika Demo testi PDF 18 (Q35). Mazmun original, manba imtihon savolining aynan nusxasi emas.');
 INSERT INTO public.algoritmlash_style_audit(question_id,source_reference,content_fingerprint,status_at_audit,format_at_audit,style_category,priority,findings,source_evidence)
 VALUES(qid,'algoritmlash-v4:ALG-V4-'||(q->>'id'),md5(coalesce(q->>'stem','')||q::text),'review',q->>'fmt',q->>'style','routine','[]'::jsonb,
 jsonb_build_object('style','source-demonstrated pattern, original problem','spec','2026 PDF 4','source_pdf_pages',jsonb_build_array('Demo2026 PDF6 Q12','20000 LIK PDF6 Q13-Q14','Informatika Demo PDF18 Q35'),'key','explanation and variants created with direct trace'));
END LOOP;
IF (SELECT count(*) FROM questions WHERE source_reference LIKE 'algoritmlash-v4:ALG-V4-%')<>24 THEN RAISE EXCEPTION 'Expected 24 V4 questions'; END IF;
END $insert$;
COMMIT;